useEffect(() => {
  const canvas = canvasRef.current;
  const context = canvas.getContext('2d');
  const image = new Image();

  image.onload = () => {
    console.log('Image loaded');
    // Set canvas size to match the image
    canvas.width = 640;
    canvas.height = 640;

    // Draw the image
    context.drawImage(image, 0, 0, 640, 640);

    // Draw the bounding boxes
    boxes.forEach(box => {
      const { x_min, y_min, x_max, y_max, class_name } = box;
      const width = x_max - x_min;
      const height = y_max - y_min;

      console.log(`Drawing box for ${class_name} at (${x_min}, ${y_min}) with width ${width} and height ${height}`);

      // Set the style for the bounding box
      context.strokeStyle = 'red'; // You can change this color based on class_name if needed
      context.lineWidth = 2;
      context.strokeRect(x_min, y_min, width, height);

      // Optionally, draw the class name and confidence
      context.fillStyle = 'red';
      context.font = '12px Arial';
      context.fillText(`${class_name}`, x_min, y_min - 5);
    });
  };

  image.src = imageUrl;
}, [imageUrl, boxes]);
